from review import card,save,DATE
i='TCS-3807';_,c=card(i);refs=c['references']
refs[0]['locator']='Section 1 defines γ-CP as factor-γ approximation; Section 3 Open Question 10 asks for an n^{1+ε} SETH lower bound at factor exactly 2.'
refs += [dict(id='full',title='On Closest Pair in Euclidean Metric: Monochromatic is as Hard as Bichromatic',authors='Karthik C. S.; Pasin Manurangsi',year=2018,url='https://arxiv.org/abs/1812.00901',pdf_url='https://arxiv.org/pdf/1812.00901v1',locator='Full version submitted 3 December 2018; concluding question repeats “any metric” and d=ω(log n) without selecting a metric/encoding or upper dimension regime.'),dict(id='barrier',title='On the Complexity of Closest Pair via Polar-Pair of Point-Sets',authors='Roee David; Karthik C. S.; Bundit Laekhanukit',year=2018,url='https://doi.org/10.4230/LIPIcs.SoCG.2018.28',pdf_url='https://drops.dagstuhl.de/storage/00lipics/lipics-vol099-socg2018/LIPIcs.SoCG.2018.28/LIPIcs.SoCG.2018.28.pdf',locator='Theorem 5 gives a (2−o(1))-approximation lower bound in ℓ∞; page 28:5 explains the construction barrier; Theorem 18 has a distance-1 versus distance-2 promise.'),dict(id='diameter',title='On Diameter Approximation in Directed Graphs',authors='Amir Abboud; Mina Dalirrooyfard; Ray Li; Virginia Vassilevska Williams',year=2023,url='https://doi.org/10.4230/LIPIcs.ESA.2023.2',locator='Publisher abstract checked: roundtrip-diameter reductions to approximate ℓ∞ Closest Pair are separate from a SETH lower bound at factor exactly 2.')]
issue='The source asks for hardness in “any metric” but does not fix an eligible metric family or say precisely whether a witness metric or a universal result is intended. A metric distance oracle, a distance matrix, and explicitly encoded vectors are different computational inputs. It also gives only d=ω(log n), without an upper dimension/coordinate-bit regime or an n,d running-time convention, so a purported n^{1+ε} lower bound can otherwise be an input-reading artifact. Finally the algorithm’s randomness and the matching deterministic versus randomized SETH hypothesis must be selected. These choices are not supplied by the question or the checked full version; no particular norm, subpolynomial dimension bound or stronger hypothesis is silently substituted.'
notes=['Corrected 2-CP to factor-two monochromatic approximation, not ℓ₂ Closest Pair or exact nearest-pair search.','Restored the existential superlinear exponent, conditional SETH scope and d=ω(log n) notation.','Read the earlier ℓ∞ theorem and distinguished its below-two gap from approximation with a closed factor-two guarantee.','Identified missing metric/input and dimension-cost quantifiers instead of inventing an efficiently represented metric or accepting an input-reading lower bound.','Searched later work, including the distinct 2023 directed-diameter reduction.']
save(i,dict(
 title='SETH hardness of factor-two Closest Pair',
 formal='The source asks whether SETH can imply a superlinear time lower bound for factor-two approximation of the monochromatic Closest Pair problem: for some constant ε>0, rule out algorithms running in O(n^{1+ε}) time on n points in dimension d=ω(log n). A factor-two algorithm must return two distinct input points whose distance is at most twice the minimum distance between any distinct input pair. The “2” denotes the approximation factor, not the Euclidean norm. The source permits “any metric” without fixing its computational representation or the full dimension regime, so this is not yet a fully specified conditional proposition.',
 definitions='A metric space (M,dist) has dist:M×M→ℝ≥0, with dist(x,y)=0 iff x=y, symmetry, and the triangle inequality. For a finite set P={p₁,…,pₙ} of n≥2 distinct points, let OPT(P)=min_{1≤i<j≤n}dist(pᵢ,pⱼ). A factor-two Closest Pair output is an index pair i<j with dist(pᵢ,pⱼ)≤2OPT(P). This is monochromatic: there is a single point set, and no red/blue constraint on the returned pair. The source studies vector spaces with distances ℓ_p(x,y)=(Σ_j|x_j−y_j|^p)^{1/p} for fixed p≥1, Hamming distance counting unequal coordinates, and in related work ℓ∞(x,y)=max_j|x_j−y_j|. The open question does not choose one of these metrics or limit “any metric” to this list. For a dimension function d(n), d=ω(log n) means d(n)/log₂n→∞ as n→∞; it imposes no upper bound such as d=n^{o(1)}. An explicit vector input has nd coordinates, whose bit lengths also affect its size. In an oracle model, evaluating a distance is instead an allowed query; in a distance-matrix model, Θ(n²) distances are part of the input. These representations cannot share an unexplained n-only running-time convention. Standard deterministic SETH says that for every η>0 there is an integer clause width w such that satisfiability of w-CNF formulas on N Boolean variables cannot be decided by a deterministic algorithm in O(2^{(1−η)N}L^{O(1)}) time, where L is the formula encoding length. Each clause has at most w literals. Ruling out bounded-error randomized SAT algorithms is a stronger randomized SETH variant; deterministic SETH alone is not automatically a hardness assumption against all randomized geometric algorithms. A factor of 2−γ, γ>0, or 2−o(1) strictly below 2 does not equal the closed guarantee ≤2OPT. In particular, a promise that OPT is 1 in one case and all distances are 2 in the other cannot by itself distinguish those cases from an arbitrary factor-two output: a distance-2 pair can be allowed in both.',
 question_type='yes_no',
 answer_criterion='First recover an intended metric family and its finite input representation, dimension and bit-length regime, cost model, quantifier over metrics, and algorithm/hypothesis randomness convention. Within that specification, establish the requested SETH implication for some constant ε>0 or refute that conditional statement. A result only below approximation factor 2, a lower bound forced by reading a larger input, a bichromatic theorem, or a barrier for one reduction construction does not settle the intended question. These remaining modeling choices are not yet certified.',
 context_blocks=[dict(title='The endpoint is the substantive target',text='The 2018 ℓ∞ theorem gives conditional near-quadratic hardness for approximation ratios strictly below 2. Its distance-1 versus distance-2 promise does not exclude a guarantee that permits equality at factor 2. The 2019 source therefore explicitly asks again about factor exactly 2.',citation='barrier'),dict(title='Exact and small-factor hardness is already known',text='The 2019 paper proves strong exact Closest Pair hardness and hardness for factors 1+δ in several ℓ_p metrics. Neither statement reaches the requested factor-two endpoint with a superlinear lower bound.',citation='primary'),dict(title='A construction barrier is not an algorithm or an impossibility theorem',text='The earlier source explains how the triangle inequality limits certain simple geometric reductions. This observation does not prove that a SETH reduction at factor 2 is impossible, nor does it supply a fast factor-two algorithm.',citation='barrier'),dict(title='Later diameter reductions address another conditional question',text='The 2023 paper relates subquadratic roundtrip-diameter approximation to approximate ℓ∞ Closest Pair. Its result is not stated as a SETH-based factor-two Closest Pair lower bound and does not supply the missing model choices here.',citation='diameter')],
 why='The factor-two threshold tests whether known fine-grained geometric hardness extends beyond the range accessible to existing reductions. Its significance is computational hardness at a fixed approximation endpoint, which requires a representation and dimension regime where the bound is not explained just by input length.',
 references=refs,progress=[dict(date='2018',text='Conditional hardness in ℓ∞ is proved for ratios below 2, alongside a triangle-inequality limitation of simple reduction gadgets.',citation='barrier'),dict(date='2019',text='The source obtains exact and small-factor hardness in ℓ_p metrics and asks for any superlinear SETH lower bound at factor exactly 2.',citation='primary'),dict(date='2023',text='Approximate ℓ∞ Closest Pair appears in separate conditional reductions for directed roundtrip diameter.',citation='diameter')],
 status='uncertain',status_note='Checked the source and its full preprint, the earlier theorem including its distance gap, and later-result searches through 12 September 2026. The exact factor-two target was not found resolved, but “any metric” and the dimension/representation-cost scope remain insufficiently specified for a complete benchmark statement. The 2023 result was checked at publisher-abstract level.',model_self_contained=False,requires_context=True,
 statement_review=dict(status='needs_specification',reviewed_on=DATE,notes=notes,remaining_issue=issue),review_note=issue,
 importance=dict(score=c['importance']['score'],method='editorial',reason='A meaningful approximation endpoint for geometric fine-grained hardness, distinct from the already established exact and below-two results. A defensible benchmark requires the unresolved metric and input-size conventions. Existing score retained.',assessed_on=DATE),
 working_summary=dict(sentences=['The question concerns returning a pair within factor two of the closest distance in one point set.','It asks whether SETH can rule out some n^{1+ε}-time algorithm in dimensions above logarithmic.','Known ℓ∞ hardness below factor two does not settle the closed factor-two guarantee.','The source’s triangle-inequality discussion is a limitation of certain reductions rather than a general impossibility theorem.','The card recovers these distinctions but still needs a metric, representation, dimension-cost regime and randomness convention.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full','barrier','diameter'])
),notes=notes,checked_sources=[r['url'] for r in refs],state='improved_unfinished')
